"""Spires section: original-host play and source-based platform choices."""
from pathlib import Path
from html import escape
from site_analytics import write_html
from guide_images import decorate
from play_recommendations import recommendations, stylesheet
from live_versions import value, when

ROOT=Path(__file__).resolve().parents[1]
P='/spires-of-azeroth/'
GAME='https://thewowdb.com/spiresofazeroth/'
RELEASE='https://github.com/Chrisl252/spiresofazeroth/releases/latest'
REPO='https://github.com/Chrisl252/spiresofazeroth'
AD='<script async src="https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client=ca-pub-8830315294299920" crossorigin="anonymous"></script>'
def ext(u,l):return f'<a href="{u}" target="_blank" rel="noopener noreferrer">{l} ↗<span class="sr-only"> (external website, opens in a new tab)</span></a>'
def ref(i):return f'<sup class="ref"><a href="#source-{i}" aria-label="Source {i}">[{i}]</a></sup>'
def sources(items):return '<section class="sources" id="sources"><h2>Sources &amp; verification</h2><ol>'+''.join(f'<li id="source-{i}">{ext(u,l)} — {d}</li>' for i,(u,l,d) in enumerate(items,1))+'</ol><a class="back" href="#guide">Back to guide ↑</a></section>'
def related():return f'<section class="related"><h2>Choose your next step</h2><p><a href="{P}#play">Play Spires of Azeroth →</a> · <a href="{P}download-platforms/">Download &amp; platform choices →</a></p><p><a href="/azeroth-survivors/#which-game">Find the right Warcraft-inspired game →</a> · <a href="/#wiki-start">More game guides →</a></p></section>'
def shell(route,title,desc,body,error=False):
    nav=f'<a href="{P}#play">Play</a><a href="{P}#how-to-play">How to play</a><a href="{P}download-platforms/">Download</a><a href="{P}#more-games">More games</a>'
    return stylesheet(f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)}</title><meta name="description" content="{escape(desc,quote=True)}"><link rel="canonical" href="https://megabonk.org{route}"><meta property="og:title" content="{escape(title,quote=True)}"><meta property="og:description" content="{escape(desc,quote=True)}"><meta property="og:type" content="website"><meta property="og:url" content="https://megabonk.org{route}"><meta property="og:image" content="https://megabonk.org/assets/spires-of-azeroth/game-1280.webp"><link rel="icon" href="/assets/spires-of-azeroth/favicon.ico"><link rel="icon" type="image/svg+xml" href="/assets/spires-of-azeroth/logo.svg"><link rel="apple-touch-icon" href="/assets/spires-of-azeroth/apple-touch-icon.png"><link rel="stylesheet" href="/assets/pokebonk/site.css"><link rel="stylesheet" href="/assets/guide-article-layout.css"><link rel="stylesheet" href="/assets/poke-survivor/play.css"><link rel="stylesheet" href="/assets/spires-of-azeroth/site.css">{('<meta name="robots" content="noindex,follow">' if error else AD)}{('<script defer src="/assets/spires-of-azeroth/play.js"></script>' if route==P else '')}</head><body class="spires guide-layout ps-play-page"><a class="skip" href="#main">Skip to content</a><header class="top"><div class="wrap"><a class="brand" href="{P}"><img src="/assets/spires-of-azeroth/logo.svg" alt="" width="42" height="42"><span>Spires of Azeroth<small>Independent play &amp; guide · Megabonk.org</small></span></a><nav class="desktop-nav" aria-label="Main navigation">{nav}</nav><details class="mobile-nav"><summary>Menu ☰</summary><nav class="mobile-links" aria-label="Mobile navigation">{nav}</nav></details></div></header><main class="wrap" id="main">{body}</main><footer class="footer"><div class="wrap footer-grid"><div><strong>Plan a turn. Climb another floor.</strong><p>Independent editorial by Megabonk.org. Spires of Azeroth is a fan project by Chrisl252 / TheWoWDB contributors. Not affiliated with the project or Blizzard Entertainment. Game artwork belongs to its respective owners.</p><a href="/#wiki-start">More games &amp; guides →</a></div><nav aria-label="Site information"><a href="/about/">About</a><a href="/contact/">Contact</a><a href="/privacy-policy#spires-of-azeroth">Privacy</a></nav></div></footer></body></html>''')

def home():
    body=f'''<header class="spires-intro" id="guide" data-play-background><div><p class="eyebrow">A WARCRAFT-INSPIRED CARD ROGUELIKE · UNOFFICIAL GUIDE</p><h1>Play Spires of Azeroth online</h1><p>Draft familiar spells. Read the enemy's next move. Climb a spire one turn at a time.</p><p>A free browser deckbuilder with nine Classic WoW classes, equipment and raid bosses. This is <strong>turn-based card combat</strong>, separate from Azeroth Survivors' automatic-spell survival runs. {ref(1)}</p></div><div class="intro-note"><span>YOUR FIRST CLIMB</span><strong>Choose a hero.<br>Build a deck.<br>Face the boss.</strong><a href="#how-to-play">Follow the starting path ↓</a></div></header>
<section class="game-panel" id="game-panel" aria-label="Spires of Azeroth game window" data-mode="normal"><div class="game-screen" id="play"><div class="game-cover" id="game-cover"><img src="/assets/spires-of-azeroth/game-1280.webp" width="1440" height="860" alt="Spires of Azeroth original browser game"><div class="cover-content"><h2>Spires of Azeroth</h2><p>Classic spells. A different hand every turn.</p><button class="play-button" id="game-launch" type="button">Play Spires of Azeroth →</button><p class="cover-note">Click to load the original at thewowdb.com.<br>No game account required for solo play.</p></div></div><iframe id="game-frame" title="Spires of Azeroth original game hosted by TheWoWDB" data-src="{GAME}" allow="autoplay; fullscreen; gamepad" allowfullscreen referrerpolicy="strict-origin-when-cross-origin" hidden></iframe></div><div class="game-meta"><div class="game-tools"><button id="game-expand" type="button" aria-pressed="false" disabled>Expand game</button><button id="game-minimize" type="button" aria-expanded="true" aria-controls="play" disabled>Hide game</button>{ext(GAME,'TheWoWDB · open original')}</div><p id="game-status" role="status" aria-live="polite">Click Play to connect. Hiding keeps the session connected; it does not pause the game.</p><p>Keep this host and browser profile for your progress. A frame and a separate tab may receive different storage treatment. <a href="/privacy-policy#spires-of-azeroth">Game-window privacy</a>.</p><noscript><p>{ext(GAME,'TheWoWDB · play original in its own tab')}</p></noscript></div></section>
<div class="game-dock" id="game-dock" hidden><span>Spires of Azeroth hidden</span><button id="game-restore" type="button">Return to game ↑</button></div>
{recommendations('spires-of-azeroth').replace('Try another survivor game, right here on Megabonk.org.','Switch from card battles to one of these survival games on Megabonk.org.')}
<div class="hub-routes" id="guides" data-play-background><a href="#how-to-play"><strong>First run</strong><span>Character → zone → map → combat</span></a><a href="#controls"><strong>Controls</strong><span>Cards, targets and ending a turn</span></a><a href="{P}download-platforms/"><strong>Download &amp; saves</strong><span>Choose a platform before moving progress</span></a></div>
<article class="play-notes" data-play-background><nav class="play-jump" aria-label="On this page"><a href="#about-game">About</a><a href="#how-to-play">How to play</a><a href="#controls">Controls</a><a href="#classes">Classes</a><a href="#help">Help</a><a href="#sources">Sources</a></nav>
<section id="about-game"><h2>A familiar world, played one card at a time</h2><p>Spires of Azeroth combines a branching roguelike climb with Warcraft-inspired spells and enemies. You choose a class, draft cards as the run develops, equip gear and tackle the bosses of each spire. Your hand and resources constrain what you can do this turn; clicking End Turn lets the enemies act. It is a fan game, not Blizzard's MMO or an expansion for Slay the Spire. {ref(1)}</p><p>The author lists nine classes and 40 Classic zones. That is the project's advertised scope, not a claim that we cleared every zone. Browser build <strong>20261103e</strong> was inspected on 4 November 2026; desktop releases have their own version numbers. {ref(2)}</p></section>
<section id="how-to-play"><h2>From Choose class to your first battle</h2><ol><li>Click Play above and wait for the game's own title menu. The outer frame loading is only the start of resource loading.</li><li>Select <strong>Choose class</strong>. With no saved character, the current version opens character creation. Choose a race and class, enter a name, then Accept.</li><li>Select the character and use <strong>Enter World</strong>. Review the starting continent and difficulty controls before entering; use the basic starting difficulty for a first look.</li><li>Choose an offered zone, then a reachable node on the map. Zone choices and encounters can vary between runs.</li><li>In combat, inspect the enemy's intent and your hand. Play a card on a valid target, then end the turn when you have finished your actions. Read the next reward before adding it to your deck.</li></ol><p>This starting path was checked in the original browser interface on 4 November. It is not a full-clear route or a strongest-class recommendation. {ref(1)}</p></section>
<section id="controls"><h2>Cards, targets and turns</h2><div class="table-wrap" tabindex="0" role="region" aria-label="Game controls"><table><thead><tr><th>Task</th><th>Mouse / keyboard</th><th>Check before acting</th></tr></thead><tbody><tr><td>Inspect a card</td><td>Hover a card; use the enlarged description</td><td>Cost, target and any keyword conditions</td></tr><tr><td>Play a card</td><td>Drag onto its target, or select the card and then its target</td><td>A card needing an enemy cannot target empty space</td></tr><tr><td>Finish your turn</td><td>End Turn button</td><td>Unspent resources and the enemy's next action</td></tr><tr><td>Pause / settings</td><td>Game Settings control or Esc</td><td>Pause inside the game before hiding the outer frame</td></tr><tr><td>Enlarge this window</td><td>Expand game above</td><td>Exit expanded view to return to this guide</td></tr></tbody></table></div><p>Prefer the visible buttons while learning. The game also has keyboard and controller support, but bindings and touch behavior can change. On a narrow screen, expand the game or use a landscape view; this is not a physical-phone compatibility guarantee. {ref(3)}</p></section>
<section id="classes"><h2>Pick a class for the decisions you enjoy</h2><p>All nine Classic class names appear in the project: Warrior, Paladin, Hunter, Rogue, Priest, Shaman, Mage, Warlock and Druid. Their card themes differ: Warrior uses stances and rage; Rogue builds and spends combo points; Druid changes forms; Mage offers Frost, Fire and Arcane spells. These are identity cues from the author's description, <strong>not a power ranking</strong>. Read the chosen class's starter deck in the game before committing. {ref(2)}</p><p>Equipment and talents add another layer to the climb. Do not copy an Azeroth Survivors talent allocation into this game: matching spell names do not make the rules or saves interchangeable. <a href="/azeroth-survivors/#which-game">Compare the game identities →</a>.</p></section>
<section id="help"><h2>Choose the right next step</h2><p><strong>Want an app?</strong> <a href="{P}download-platforms/">Choose Windows, macOS, Linux, Android or the iOS browser route</a>. The author's desktop packages need the internet on first use and do not automatically share your browser progress. {ref(2)}</p><p><strong>Blank or stalled game?</strong> Allow resources to load, then try {ext(GAME,'TheWoWDB · original in its own tab')}. Note the host, displayed build and exact error. Do not clear site data as a first step: it can remove progress. An external game outage cannot be repaired by refreshing this guide.</p><p><strong>Returning to a run?</strong> Use the same host and browser profile and look for Continue run in the game. Before switching versions, use its own save export where available and keep both source and destination backups. We have not verified cross-platform imports, co-op completion or every browser. {ref(3)}</p></section>
{sources([(GAME,'TheWoWDB · original game','Original interface and short startup inspection, 4 November 2026. Game artwork © Blizzard Entertainment / respective owners; no full clear or physical-phone test.'),(REPO,'GitHub · Chrisl252/spiresofazeroth','Author description, platform notes and project scope, checked 4 November 2026. Not an independent benchmark.'),(GAME+'js/main.js?v=20261103e','TheWoWDB · browser source','Build 20261103e source and menu flow checked 4 November 2026; controls and persistence implementation, not proof that every device or import works.')])}{related()}</article>'''
    return shell(P,'Spires of Azeroth: Play Online & Guide | Megabonk','Play Spires of Azeroth in an original-host browser window. Learn the card-combat loop, first-run controls, platform choices and separate saves.',body)

def download():
    body=f'''<nav class="crumbs"><a href="{P}">Spires of Azeroth</a> / Download &amp; platforms</nav><header class="article-head" id="guide"><span class="tag">DOWNLOAD &amp; SAVE CHOICES</span><h1>Spires of Azeroth download &amp; platform choices</h1><div class="answer"><p>Play in a browser with no installation, or get the author's desktop and Android packages from GitHub. For iPhone or iPad, the original menu points to Safari's Add to Home Screen. <strong>App saves and browser saves are separate.</strong> Choose your route before starting a long run. {ref(1)}{ref(2)}</p></div><p class="meta">Megabonk.org editorial · Checked 4 November 2026 · Source and menu inspection; apps not installed</p></header><div class="article-layout"><aside class="toc"><strong>On this page</strong><a href="#choose">Choose a platform</a><a href="#saves">Saves &amp; versions</a><a href="#ios">iPhone / iPad</a><a href="#which-game">Correct game</a><a href="#help">Help</a></aside><article class="prose">
<section id="choose"><h2>Choose browser or the correct app package</h2><div class="table-wrap" tabindex="0" role="region" aria-label="Platform download choices"><table><thead><tr><th>Your platform</th><th>Route</th><th>Before you commit</th></tr></thead><tbody><tr><td>Desktop browser</td><td><a href="{P}#play">Use the original-host game window</a>, or open the original in its own tab</td><td>Keep the same host and browser profile for returning progress</td></tr><tr><td>Windows x64</td><td>Author's .exe setup or .msi on GitHub releases</td><td>These are unsigned packages; this guide is not a security audit</td></tr><tr><td>macOS</td><td>Author's universal .dmg</td><td>Package signing and compatibility are the author's responsibility</td></tr><tr><td>Linux</td><td>AppImage, .deb or .rpm matching your system</td><td>Use the format appropriate to your distribution</td></tr><tr><td>Android</td><td>Author's .apk</td><td>Use the author-linked release, not another game's APK</td></tr><tr><td>iPhone / iPad</td><td>Safari → Share → Add to Home Screen</td><td>This is a web-app route, not a verified App Store release</td></tr></tbody></table></div><p>{ext(RELEASE,'GitHub · author releases and platform files')} · {ext(GAME,'TheWoWDB · original browser game')}. Follow the platform instructions provided with the release. We have not installed or audited the binaries and do not recommend disabling system protections. {ref(1)}{ref(2)}{ref(3)}</p><p>The original Download menu is useful when returning later: it links to the author's latest release rather than an unrelated mirror. The screenshot below identifies that menu; it is not evidence of successful installation.</p></section>
<section id="saves"><h2>Separate the browser build, app package and saved progress</h2><ol><li><strong>Identify what you already use.</strong> Write down the full host, browser profile and displayed build before changing anything.</li><li><strong>Back up first.</strong> Use the current game's own export controls where available; keep a copy outside the game. If the destination has progress, back that up separately too.</li><li><strong>Choose the destination deliberately.</strong> The author says desktop saves do not automatically carry over from the browser. A framed browser and a separate tab may also have different storage treatment.</li><li><strong>Check the result before abandoning the old copy.</strong> This page does not establish successful cross-version or cross-platform import compatibility.</li></ol><p>At our latest automated version check, the browser source declared {value('spires-browser')} (recorded {when('spires-browser')}), while GitHub's latest package release was {value('spires-desktop')}, published {when('spires-desktop')}. They are different version labels; a newer browser build does not prove that a downloaded package includes the same changes. {ref(3)}{ref(4)}</p><p>The author says the apps fetch and cache art, models and sound from TheWoWDB on first use. Have a connection for that first launch; do not treat a small installer as proof that the complete game is bundled for offline play. {ref(2)}</p></section>
<section id="ios"><h2>iPhone and iPad: the menu's Safari route</h2><p>Open {ext(GAME,'TheWoWDB · original game')} in Safari, use Share, then Add to Home Screen, as instructed by the original Download panel. This adds a browser-based entry. It does not establish an iOS native app, touch compatibility on every device, or shared progress with your desktop browser. {ref(1)}</p><p>For reading small cards, try a landscape view or a larger screen. Our checks use browser viewport sizes; they are not physical-iPhone or iPad installation tests.</p></section>
<section id="which-game"><h2>Check the name before downloading</h2><p><strong>Spires of Azeroth</strong> is this turn-based card roguelike at TheWoWDB. “Spire of Azeroth” may be a shortened search spelling. <strong>Azeroth Survivors</strong> is Aethus's separate survival game: use <a href="/azeroth-survivors/download-platforms/">its own platform and source guide</a>. Packages, class builds and saves are not interchangeable. {ref(2)}</p><p>There is also a 2012 Minecraft map called Spires of Azeroth. Its map downloads and texture packs are unrelated to this card game. Verify the author-linked GitHub repository <code>Chrisl252/spiresofazeroth</code> rather than choosing a file from the shared name alone. {ref(5)}</p></section>
<section id="help"><h2>If your route does not work</h2><p>If the app cannot complete its first resource load, check the author's latest release notes and the original browser entry. Report the platform, package version and exact error to the project's support channel linked from the current game or repository. A browser startup check does not prove an app will fix your device issue.</p><p>If the embedded browser window is blank, open the same original in a new tab. Preserve existing progress; do not clear storage or overwrite a save merely to test another entry. <a href="{P}#how-to-play">Return to the first-run steps →</a>.</p></section>
{sources([(GAME,'TheWoWDB · original Download panel','Captured 4 November 2026, browser BUILD 20261103e. Lists desktop/Android routes and Safari home-screen instructions; no app installation test.'),(REPO+'#download-for-desktop','GitHub · author download notes','Read 4 November 2026: unsigned builds, separate desktop/browser saves and first-use resource fetching. Author documentation, not a compatibility or security audit.'),('https://github.com/Chrisl252/spiresofazeroth/releases/tag/v1.0.2','GitHub · v1.0.2 release','29 October 2026; eight binary assets verified via the public release API on 4 November. Availability can change.'),(GAME+'js/version.js?v=20261103e','TheWoWDB · version source','BUILD 20261103e at the 4 November check; separate from desktop package version.'),('https://www.planetminecraft.com/project/spires-of-azeroth/','Planet Minecraft · lynchyinc map','2012 map; different entity, not a download route for the card game.')])}{related()}</article></div>'''
    return shell(P+'download-platforms/','Spires of Azeroth Download & Platforms | Megabonk','Choose Spires of Azeroth browser, Windows, Mac, Linux or Android routes. Check iOS home-screen instructions, first-launch internet and separate saves.',body)

def build():
    for route,text in [(P,home()),(P+'download-platforms/',download()),(P+'404.html',shell(P+'404','Page not found | Spires of Azeroth','Find the game window and platform guide.',f'<article class="legal"><h1>Page not found</h1><p>Return to <a href="{P}">Spires of Azeroth</a> or <a href="{P}download-platforms/">choose a platform</a>.</p></article>',True))]:
        f=ROOT/route.lstrip('/') if route.endswith('.html') else ROOT/route.lstrip('/')/'index.html'
        f.parent.mkdir(parents=True,exist_ok=True)
        write_html(f,decorate(route,text),encoding='utf8')
    f=ROOT/'index.html';text=f.read_text(encoding='utf8')
    if 'id="spires-game-entry"' not in text:
        text=text.replace('<div class="route-grid">','<div class="route-grid"><a class="route-card" id="spires-game-entry" href="/spires-of-azeroth/"><h3>Spires of Azeroth</h3><p>Turn-based Warcraft-inspired card combat: play the original, learn the controls and choose a platform.</p><span class="route-link">Play &amp; guide →</span></a>',1)
        write_html(f,text,encoding='utf8')
    f=ROOT/'privacy-policy.html';text=f.read_text(encoding='utf8')
    if 'id="spires-of-azeroth"' not in text:
        text=text.replace('</body>','<h2 id="spires-of-azeroth">Spires of Azeroth game window</h2><p>Updated 4 November 2026. Clicking Play loads the original game from thewowdb.com, including its resources and services. The game host receives technical request data and controls its own storage and any consent choices shown inside the game. Hiding keeps the same frame connected and does not pause it; close or leave the page to end the session. Framed and separate-tab storage can differ; we cannot read or recover game saves. Downloads link externally to the author\'s GitHub releases; we do not install files or upload saves. Ordinary section pages inherit this site\'s existing AdSense and site-wide Umami services. Cloudflare hosting may add performance measurement to pages, including error responses, as described above.</p></body>',1)
        write_html(f,text,encoding='utf8')
    print('Built Spires playable hub, platform task and scoped404; patched root entry/privacy.')
if __name__=='__main__':build()
